const trigger = $('Email Trigger (IMAP)').item.json;
const raw = (trigger.textPlain || trigger.textHtml || '').replace(/\r\n/g, '\n');
const ai = $json.output || {};

const norm = s => (s || '').replace(/\s+/g, ' ').trim();

// Locate the line reported by the model: exact match, then whitespace-insensitive, then by prefix.
function findMarker(text, marker) {
  const m = (marker || '').trim();
  if (m.length < 4) return -1;
  const exact = text.indexOf(m);
  if (exact > -1) return exact;
  const target = norm(m);
  const prefix = target.slice(0, 30);
  let pos = 0;
  for (const line of text.split('\n')) {
    const nl = norm(line);
    if (nl && (nl === target || nl.startsWith(prefix))) return pos;
    pos += line.length + 1;
  }
  return -1;
}

// Deterministic safety net for when the model misses a marker.
const quotedPatterns = [
  /^-{2,}\s*(Original Message|Mensaje original|Forwarded message|Mensaje reenviado)\s*-{2,}\s*$/im,
  /^(El|On) .{5,150}(escribi[oó]|wrote):\s*$/im,
  /^(De|From):\s.+\n(Enviado|Sent|Para|To|Fecha|Date):/im,
  /^>\s?\S/m,
];
const signaturePatterns = [
  /^-- ?$/m,
  /^(Saludos|Un saludo|Atentamente|Cordialmente|Gracias|Best regards|Kind regards|Regards|Cheers|Thanks),?\s*$/im,
  /AVISO (DE )?(LEGAL|CONFIDENCIALIDAD)|CONFIDENTIALITY NOTICE|DISCLAIMER/i,
  /Este (mensaje|correo)[^\n]{0,60}(anexos|adjuntos|ficheros|confidencial)/i,
  /This (e-?mail|message)[^\n]{0,80}(confidential|intended)/i,
];

function firstMatch(text, patterns) {
  let best = -1;
  for (const re of patterns) {
    const m = re.exec(text);
    if (m && (best === -1 || m.index < best)) best = m.index;
  }
  return best;
}

let quotedIdx = ai.has_quoted_content ? findMarker(raw, ai.quoted_start) : -1;
if (quotedIdx === -1) quotedIdx = firstMatch(raw, quotedPatterns);

let signatureIdx = ai.has_signature ? findMarker(raw, ai.signature_start) : -1;
if (signatureIdx === -1) signatureIdx = firstMatch(raw, signaturePatterns);

// A marker within the first few characters is a false positive, never cut there.
const MIN_BODY = 20;
const cuts = [quotedIdx, signatureIdx].filter(i => i >= MIN_BODY);
const cutAt = cuts.length ? Math.min(...cuts) : -1;
const cleanBody = (cutAt > -1 ? raw.slice(0, cutAt) : raw).trim();

const strippedQuoted = quotedIdx >= MIN_BODY;
const strippedSignature = signatureIdx >= MIN_BODY;

const notes = [];
if (strippedQuoted) notes.push('This was a forward or reply and some extra text was stripped out.');
if (strippedSignature) notes.push('This email had a signature or legal notice on it.');

return {
  json: {
    from: trigger.from,
    subject: trigger.subject,
    date: trigger.date,
    clean_body: cleanBody,
    stripped_quoted: strippedQuoted,
    stripped_signature: strippedSignature,
    notes,
    debug: { cutAt, quotedIdx, signatureIdx, originalLength: raw.length, ai },
  },
};

const strip = $('Strip body').item.json;
const translated = String($json.text ?? $json.output ?? '').trim();
const footer = (wrap) => strip.notes.length
  ? '\n\n' + strip.notes.map(wrap).join('\n')
  : '';

return {
  json: {
    from: strip.from,
    subject: strip.subject,
    date: strip.date,
    translated,
    notes: strip.notes,
    message: translated + footer(n => `_${n}_`),
  },
};
